const p = msg.payload;
const kind = p.lifecycleType || 'active_transition';

if (kind === 'active_interval') {
    node.status({ fill: 'yellow', shape: 'dot', text: `interval tick @ ${p.state}` });
} else if (p.changed) {
    node.status({ fill: 'green', shape: 'dot', text: `transition -> ${p.state}` });
} else {
    node.status({ fill: 'blue', shape: 'dot', text: `retrigger ${p.state}` });
}

msg.topic = kind;
return msg;

const p = msg.payload;
const kind = p.lifecycleType || 'active_transition';

if (kind === 'active_interval') {
    // Periodic tick: the state is still RUNNING and the prior cycle resolved.
    // With skip policy this will fire only after the prior response resolved the cycle.
    node.status({ fill: 'yellow', shape: 'ring', text: 'interval: still RUNNING' });
} else {
    // Transition or retrigger emission.
    node.status({ fill: 'green', shape: 'dot', text: `entered RUNNING (event ${p.eventId})` });
}

return msg;
